WITH base AS (SELECT *, UPPER(page) AS page_upper, COALESCE(page, 'DIRECT') AS page_filled FROM web_events WHERE event_time >= DATE '2023-08-09' AND page IS NOT NULL), flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM base), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT session_id, BIT_OR(duration_sec) AS duration_sec_bit_or, APPROX_PERCENTILE(island_id, 0.95) AS island_id_p95 FROM sessionized GROUP BY session_id HAVING duration_sec_bit_or >= 1 ORDER BY session_id
